return {rwnpc01={id="rwnpc01",dsc="她生得曼妙，一举一动皆婀娜妩媚，据传出身自烟柳之地，但一支玉笛柔曲藏杀意，一手掌法棉里裹刀剑，武艺不低于江湖中的高手。",sex="女",age=27,looks=26,showequip={},withCorpse=0},rwnpc02={id="rwnpc02",dsc="她衣着显贵，是贵家之女，怀抱一只金眸玄猫，和平遥公主关系极好。",sex="女",age=19,looks=28,showequip={},withCorpse=0},rwnpc03={id="rwnpc03",dsc="他是蓬莱长老云清晏，水绿锦袍罩身，面容俊朗，气质飘逸，一手玉笛吹的出神入化，性情洒脱，偏爱洞庭景致，守关只为切磋武学、交天下侠士。",sex="男",age=56,looks=21,showequip={},withCorpse=0},rwnpc04={id="rwnpc04",dsc="他是全真教长老马清德。身着月白道袍，面容清癯，鬓发染霜，手持拂尘，眼神温润却藏锋芒，性情温和，奉命守关，以武会友。",sex="男",age=68,looks=21,showequip={},withCorpse=0},rwnpc05={id="rwnpc05",dsc="她是昆仑当代弟子之一，一身银色劲装，身姿挺拔，肌肤胜雪，眉眼清冷，身法轻盈，精通昆仑剑法，性情孤傲，一心守护门派荣誉，需过她这关方可登楼。",sex="女",age=24,looks=25,showequip={},withCorpse=0},rwnpc06={id="rwnpc06",dsc="他是金钱帮此地主事，锦缎劲装着身，身材魁梧，面容威严，腰间挂金铃，衣着华贵却不显浮夸，性情豪爽，重情重义，前来此处是想遴选强者加入帮中。",sex="男",age=45,looks=20,showequip={},withCorpse=0},rwnpc07={id="rwnpc07",dsc="皇帝最宠爱的小女儿，与福王平王一起长大，喜欢舞刀弄枪。",sex="女",age=20,looks=27,showequip={},withCorpse=0},rwnpc08={id="rwnpc08",dsc="他是此地丐帮的执法长老，虽然一身打满补丁的布衣，但身形魁梧，面容黝黑，手持打狗棒，性情豪爽，重情重义，心怀天下苍生，此次前来是为筛选心怀侠义之人。",sex="男",age=55,looks=18,showequip={},withCorpse=0},rwnpc09={id="rwnpc09",dsc="他是少林寺此地住持圆业大师，身着少林僧袍，手持禅杖，面容慈祥，身材魁梧，性情温和，此次前来一为论佛讲禅，二为寻有缘之人。",sex="男",age=70,looks=20,showequip={},withCorpse=0},rwnpc10={id="rwnpc10",dsc="他是天狼教长老洛惊风，一身灰黑劲装，年纪轻轻就身居教内高位，面容凶悍，眼角有一道刀疤，此次奉教主之命守关。",sex="男",age=32,looks=20,showequip={},withCorpse=0},rwnpc11={id="rwnpc11",dsc="他是虚渺宫长老沈听澜，他不佩剑，不持笛，唯有一双玄丝手套，十指缠着控弦丝——以潮声为律，以弦丝为器。",sex="男",age=27,looks=60,showequip={},withCorpse=0},rwnpc12={id="rwnpc12",dsc="他是雪山寺长老洛桑法师，身着藏红僧袍，身材魁梧，光头赤足，脖颈挂着白骨佛珠，手持大环锡杖，口中念着佛语，此次前来望与江湖侠士以武辨经。",sex="男",age=62,looks=24,showequip={},withCorpse=0},rwnpc13={id="rwnpc13",dsc="他是幽冥教当代弟子之一，身着玄黑宽袍，头戴高帽，身法鬼魅，面色如纸，行事残忍，恪守教中规矩，此次奉师命前来一证自身实力。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc14={id="rwnpc14",dsc="他是官府的一名兵器教头，打着文武袖，身材挺拔，面容威严，不怒自威，擅使各类长兵，性情严谨，公正不阿，此次受平遥公主之邀，来此一会江湖豪杰。",sex="男",age=40,looks=21,showequip={},withCorpse=0},rwnpc15={id="rwnpc15",dsc="他是天竞门当代弟子之一，一身素色长袍，身姿矫健，面容俊朗，眼神锐利，精通天